    let cancel_frame= if agent.kind() == *FIGHTER_KIND_BAYONETTA {48.0} else {48.0};
    if agent.is_status(statuses::bayonetta::SPECIAL_N_CANCEL) {
        MotionModule::set_rate(boma, (cancel_frame - 1.0)/base_endlag);
